static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract the year, month, and day from the time bucket
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the number of days since the start of the month
    int daysInMonth[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
        daysInMonth[1] = 29; // Leap year
    }
    int daysSinceStartOfMonth = 0;
    for (int i = 0; i < month - 1; i++) {
        daysSinceStartOfMonth += daysInMonth[i];
    }
    daysSinceStartOfMonth += day;

    // Calculate the new day based on the dayStep
    int newDay = (daysSinceStartOfMonth / dayStep) * dayStep + 1;

    // Adjust the new day if it exceeds the number of days in the month
    if (newDay > daysInMonth[month - 1]) {
        newDay = daysInMonth[month - 1];
    }

    // Reconstruct the time bucket with the new day
    return year * 10000 + month * 100 + newDay;
}

