private Map<String, Object> buildContent(JsonObject jsonObject) {
    Map<String, Object> contentMap = new HashMap<>();

    // Iterate over the entries in the JsonObject
    for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
        String key = entry.getKey();
        JsonElement value = entry.getValue();

        // Check the type of the JsonElement and convert it to the appropriate Java type
        if (value.isJsonPrimitive()) {
            JsonPrimitive primitive = value.getAsJsonPrimitive();
            if (primitive.isString()) {
                contentMap.put(key, primitive.getAsString());
            } else if (primitive.isNumber()) {
                contentMap.put(key, primitive.getAsNumber());
            } else if (primitive.isBoolean()) {
                contentMap.put(key, primitive.getAsBoolean());
            } else if (primitive.isJsonNull()) {
                contentMap.put(key, null);
            }
        } else if (value.isJsonObject()) {
            contentMap.put(key, buildContent(value.getAsJsonObject()));
        } else if (value.isJsonArray()) {
            JsonArray jsonArray = value.getAsJsonArray();
            List<Object> list = new ArrayList<>();
            for (JsonElement arrayElement : jsonArray) {
                if (arrayElement.isJsonObject()) {
                    list.add(buildContent(arrayElement.getAsJsonObject()));
                } else if (arrayElement.isJsonPrimitive()) {
                    JsonPrimitive primitive = arrayElement.getAsJsonPrimitive();
                    if (primitive.isString()) {
                        list.add(primitive.getAsString());
                    } else if (primitive.isNumber()) {
                        list.add(primitive.getAsNumber());
                    } else if (primitive.isBoolean()) {
                        list.add(primitive.getAsBoolean());
                    } else if (primitive.isJsonNull()) {
                        list.add(null);
                    }
                }
            }
            contentMap.put(key, list);
        }
    }

    return contentMap;
}

