public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int i = 0;
    int length = str.length();
    while (i < length) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < length) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case 'n':
                        sb.append('\n');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case 'b':
                        sb.append('\b');
                        break;
                    case '"':
                        sb.append('"');
                        break;
                    case '\'':
                        sb.append('\'');
                        break;
                    case '\\':
                        sb.append('\\');
                        break;
                    default:
                        throw new Exception("Invalid escape sequence: \\" + nextChar);
                }
                i += 2;
            } else {
                throw new Exception("Invalid escape sequence at end of string");
            }
        } else {
            sb.append(c);
            i += 1;
        }
    }
    return sb.toString();
}

