public static String applyRelativePath(String path, String relativePath) {
    if (relativePath.startsWith("/")) {
        // If relativePath is absolute, return it directly
        return relativePath;
    }

    // Split the path and relativePath by "/"
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    // Use a LinkedList for easy removal of parts
    LinkedList<String> resultParts = new LinkedList<>(Arrays.asList(pathParts));

    // Process each part of the relativePath
    for (String part : relativePathParts) {
        if (part.equals("..")) {
            // Move up one directory
            if (!resultParts.isEmpty()) {
                resultParts.removeLast();
            }
        } else if (!part.equals(".")) {
            // Add the part to the result
            resultParts.add(part);
        }
    }

    // Join the parts back together with "/"
    return String.join("/", resultParts);
}

